# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 mordere，分词词干 mors-','咬；咬下、咬住']]
R=B+[['拉丁 remordere → 中世纪拉丁 remorsus / remorsum','咬回来；使心里受折磨'],['古法语 remors → 英语 remorse','因做错事而受到的内心谴责']]
W=[
E('remorse','英 /rɪˈmɔːs/；美 /rɪˈmɔːrs/','懊悔；悔恨；内疚','做过的错事像回过头来咬自己，心里因此不好受。','拉丁 re- 回、加强 + mordere 咬 → remordere 使人受折磨；经中世纪拉丁名词和古法语 remors 进入英语。咬回来是词源帮助理解的画面，不是说现实里真有牙齿。',R,'remorse 往往带着道德上的自责：我做错了，或伤害了别人。错过便宜机票也会 regret，但通常不会因此产生 remorse。它比单纯可惜更重，因为你责备的是自己的行为。','feel remorse；show remorse；remorse for what one did。','regret 可以只是遗憾，remorse 更强调因自己的错误而内疚。说对方 showed no remorse，指没有表现出悔意，不只是没有说一句 sorry。',('She felt deep remorse for betraying her friend’s trust.','她因为辜负朋友的信任而深感悔恨。'),('His apology showed real remorse for the harm he had caused.','他的道歉表现出对自己造成伤害的真切悔意。'),sources=['https://www.etymonline.com/word/remorse','https://www.oxfordlearnersdictionaries.com/definition/english/remorse']),
E('remorseful','英 /rɪˈmɔːsfl/；美 /rɪˈmɔːrsfl/','懊悔的；内疚的','一个人被悔意占据，知道自己做错了，也为此难受。','英语 remorse + -ful，表示充满悔意；保留 remorse 末尾的 e，再接 -ful。',R+[['英语 remorse + -ful → remorseful','悔意 → 怀着悔意的']],'可形容人，也可形容表情、语气或道歉。a remorseful apology 强调说话者显露出自责，而不是只为避免麻烦而走个道歉流程。是否真正后悔仍要结合行为判断，形容词本身只是叙述者的描述。','feel remorseful；look remorseful；remorseful about / for something。','remorseful 不只是 sad 难过；它把难过与自己做过的错事联系起来。受到委屈很 sad，却不一定有理由 remorseful。',('He looked remorseful after realizing how much his words had hurt her.','意识到自己的话让她多么受伤后，他显得很内疚。'),('She was remorseful about spreading the rumour.','她对自己传播那个谣言感到懊悔。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/remorseful','https://en.wiktionary.org/wiki/remorseful']),
E('remorseless','英 /rɪˈmɔːsləs/；美 /rɪˈmɔːrsləs/','毫无悔意的；冷酷无情的；不停加剧的','人做了坏事却没有被良心咬痛；再把这种不肯停手的无情感，借给压力、侵蚀等事物。','英语 remorse + -less 无，起点是没有悔意；随后可形容无情、持续不停的过程。',R+[['英语 remorse + -less → remorseless','没有悔意 → 无情；不肯停歇']],'形容人时，常带很强的负面评价。形容 remorseless pressure 或 remorseless erosion 时，则把过程拟人化：它不体谅人，不会因为造成麻烦就停下。后一种用法接近 relentless，而不必真有一个做错事的人。','a remorseless criminal；remorseless pressure；the remorseless passage of time。','remorseful 是有悔意，remorseless 是无悔意；写过程时，remorseless 又可表示无情地持续。不要把 -less 翻成悔恨少一点，它通常是缺乏悔意。',('The character remains remorseless even after seeing the damage he caused.','这个人物即使看到自己造成的伤害，仍然毫无悔意。'),('The remorseless pressure of work left her exhausted.','工作带来的持续重压让她疲惫不堪。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/remorseless']),
E('morsel','英 /ˈmɔːsl/；美 /ˈmɔːrsl/','一小口；一小块食物；少量信息','从咬下的一口，想到手里或盘子里那一小块。','拉丁 morsum 咬下的一口，关联 mordere 咬；经古法语表示小块的 morsel 进入英语。-el 在这段词史里有小称作用，不是现代英语随意给食物加的后缀。',B+[['拉丁 morsum → 古法语 morsel','咬下的一口 → 一小口、一小块'],['英语 morsel','少量食物；比喻一丁点内容']],'最自然的是 a morsel of food，一点点食物。也可以写 a morsel of information，把消息当成一口可吃的小东西，通常带一点形象或书面色彩。它强调小份，未必是吃剩的碎屑。','a morsel of food；a tasty morsel；a morsel of information。','morsel 是一小份或一小口，crumb 更像掉下来的碎屑。not a morsel left 强调一点吃的也没留下，语气比只说没剩饭更形象。',('The bird picked up a morsel of bread from the path.','那只鸟从小路上叼起了一小块面包。'),('Reporters were eager for any morsel of information about the talks.','记者们急切地想得到有关谈判的哪怕一点消息。'),sources=['https://www.etymonline.com/word/morsel','https://www.oxfordlearnersdictionaries.com/definition/english/morsel']),
E('mordant','英 /ˈmɔːdənt/；美 /ˈmɔːrdənt/','尖刻的；讽刺辛辣的；媒染剂','一句话像长了牙，听着锋利，甚至让人有点疼。','来自法语 mordant 咬人的、尖刻的，是 mordre 咬的现在分词；mordre 源于拉丁 mordere。英语里的 -ant 不是蚂蚁 ant。',B+[['拉丁 mordere → 法语 mordre / mordant','咬 → 正在咬的、尖刻的'],['英语 mordant','语言辛辣的；另有染色材料名词义']],'评论里常见 mordant wit、mordant humour：有机智，也有刺，常借讽刺揭露荒谬。染色领域的名词 a mordant 则指帮助染料在材料上固着的媒染剂，可以用让颜色咬住布料作记忆画面，但这不是完整的化学机理说明。','mordant wit；mordant humour；use a mordant。','mordant 往往兼有锋利和机智，rude 只需粗鲁就成立。写染色工艺时，a mordant 是一种材料，不能译成一个尖刻的人。',('Her review was full of mordant observations about office life.','她的评论里满是对办公室生活的辛辣观察。'),('The dyer used a mordant to help the colour bind to the fabric.','染色师使用媒染剂，帮助颜色固着在织物上。'),sources=['https://www.etymonline.com/word/mordant','https://www.oxfordlearnersdictionaries.com/definition/english/mordant','https://www.merriam-webster.com/dictionary/mordant'])
]
ROOT=dict(id='C0766',meaning='咬；咬住',core='MORD / MORS = BITE',image='牙齿咬一口是 morsel；话语咬人是 mordant；错事回过头咬自己的良心，是 remorse 的记忆画面。',intro='拉丁 mordere 表示咬，分词相关形式里出现 mors-。英语经过法语等路线留下不同拼写。这个词族最值得记的不是所有单词都像咬，而是同一个身体动作怎样被借来谈食物、语言和内心感受。',forms='mordant 保留 mord-；morsel、remorse 保留 mors-。remorseful 与 remorseless 是英语中在 remorse 后接 -ful / -less，容易组成有悔意、无悔意这一对。',branches=[['一小口食物','morsel'],['语言像牙齿一样锋利','mordant'],['内心受到谴责','remorse、remorseful、remorseless']],contrasts='remorse 比一般遗憾更有自责意味；mordant 比一般粗鲁更强调尖刻机智。mors- 咬的这条线不要仅凭外形与 mort- 死亡的词直接混合。',practice='His mordant joke caused real hurt, and he later felt remorse.\n\n他那句尖刻的玩笑确实伤了人，后来他感到懊悔。',words=[x['word'] for x in W],exclude={w:'冷门音乐、植物学或低频派生词，按用户要求暂略' for w in ['mordent','mordacious','mordacity','mordancy','mordente','mordicancy','mordicant','mordication','mordicative','morsitation','premorse']})
if __name__=='__main__':
 for name,data in [('roots_mord',[ROOT]),('words_mord',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
